window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-4fba55216efbae96"]={"versions": [{"id": "FIG-4fba55216efbae96", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Sequenzdiagramm mit Interaktionsreferenz (<code>ref</code>).</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Adaptive Platform (Release R24-11), Spezifikation <em>AUTOSAR_AP_EXP_SWArchitecture</em>, Kapitel 11 (<em>System Lifecycle Management</em> / <em>Recover from Supervision Failure</em>).</li>\n<li><strong>Technischer Zweck:</strong> Darstellung des kanonischen Recovery-Pfads (<em>Recover by System State Change</em>) nach Auftreten eines Überwachungsfehlers (Supervision Failure). Es demonstriert die strikte Entkopplung zwischen Fehlerdetektion (Platform Health Management, PHM) und Fehlerbehebungsstrategie (State Management, SM) unter Einbeziehung des Prozess-Lifecycle-Managers (Execution Management, EM).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Beteiligte Functional Cluster (Lebenslinien):</strong></li>\n<li><code>«aapFunctionalCluster» :Platform Health Management</code> (PHM): Überwacht Alive-, Deadline- und Logical-Supervisions sowie Health-Channels von Prozessen und Anwendungen.</li>\n<li><code>«aapFunctionalCluster» :State Management</code> (SM): Zentraler Koordinator für Systemzustände, Funktionsgruppenzustände (Function Group States) und fahrzeugspezifische Recovery-Entscheidungen.</li>\n<li><code>«aapFunctionalCluster» :Execution Management</code> (EM): Verantwortlich für Start, Stopp, Determinismus und Zustandsübergänge konfigurierter Prozesse/Function Groups.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong>Stereotypen & Notationen:</strong></li>\n<li><code>«aapFunctionalCluster»</code>: Kennzeichnet funktionale Plattform-Kernkomponenten der AUTOSAR Adaptive Platform.</li>\n<li><code>«aapInformative»</code>: Markiert nicht-normative Schnittstellen, interne Kontrollflüsse oder exemplarische Hilfsfunktionen, die nicht als feste C++-API standardisiert sind.</li>\n<li><code>ref</code>: UML-Interaktionsreferenz auf das ausgelagerte Sub-Szenario <code>Change System State</code>.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong>Schnittstellen & Operationen:</strong></li>\n<li><code>Offer()</code>: Service-Bereitstellung / Registrierung des Recovery-Interfaces von SM gegenüber PHM (typischerweise IPC/ara::com-basiert oder plattform-interne Kopplung).</li>\n<li><code>supervisionFailed()</code> (<code>«aapInformative»</code>): Interner oder watchdog-getriebener Trigger bei Verletzung einer definierten Überwachungsregel (Checkpoint-Zeitfenster, Alive-Zähler, Graph-Traversierung).</li>\n<li><code>handleFailedSupervision()</code> (<code>«aapInformative»</code>): PHM-interne Regelauswertung und Zuordnung der fehlgeschlagenen Supervision zu einer konfigurierten Recovery-Aktion.</li>\n<li><code>RecoveryHandler()</code>: Normative Callback-/Ereignisschnittstelle von PHM an SM zur Signalisierung des aufgetretenen Fehlers samt Kontext.</li>\n<li><code>determineDesiredFGState(): desiredState</code> (<code>«aapInformative»</code>): SM-interne Entscheidungstabelle/Regelwerk zur Bestimmung des neuen Zielzustands der betroffenen Function Group(s).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Initialisierung / Service Offer:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>State Management</code> bietet seine Service-Schnittstelle via <code>Offer()</code> an, sodass PHM den Recovery-Kanal auflösen und binden kann.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Fehlerdetektion (Supervision Failure):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Ein Prozess verletzt eine Überwachungsbedingung. PHM registriert dies über den Trigger <code>supervisionFailed()</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>PHM-interne Evaluierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>PHM führt <code>handleFailedSupervision()</code> aus und ermittelt anhand des <em>Health Channel / Supervision Mapping</em> im Manifest, dass eine Systemreaktion via State Management konfiguriert ist.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Fehlersignalisierung an SM:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>PHM ruft synchron oder asynchron <code>RecoveryHandler()</code> am State Management auf und übergibt die Identifikatoren der gescheiterten Supervision.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Zielzustandsermittlung im SM:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>SM führt <code>determineDesiredFGState()</code> aus. Abhängig von Sicherheitskonzept und Kontext wird ein neuer <code>desiredState</code> für die betroffene Function Group bestimmt (z. B. Fallback auf sicheren Zustand, Degradation oder Neustart-Zustand). Hinweis: Der Zustand kann formal dem aktuellen Zustand entsprechen, falls ein lokaler Prozess-Neustart innerhalb derselben State-Definition projektiert ist.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Zustandstransition via Execution Management:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Übergang in das referenzierte Sequenzfragment <code>ref Change System State</code>: SM interagiert über die <code>ara::exec::StateClient</code>-API mit <code>Execution Management</code>, um die Zielzustände der Function Groups einzusteuern. EM stoppt oder reinitialisiert die entsprechenden Prozesse deterministisch.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Architekturprinzip (Separation of Concerns):</strong> PHM terminiert oder manipuliert in diesem Szenario keine Prozesse eigenmächtig. Die Hoheit über Prozess-Lifecycles liegt exklusiv bei <code>Execution Management</code>, gesteuert durch die fahrzeugspezifische Richtlinienkomponente <code>State Management</code>.</li>\n<li><strong>Implementierungsverantwortung (OEM vs. Tier-1/Stack-Vendor):</strong></li>\n<li>PHM und EM sind standardisierte BSW-Cluster des Stack-Herstellers.</li>\n<li>Das State Management (inkl. <code>RecoveryHandler</code>-Reaktion und <code>determineDesiredFGState</code>) ist maßgeblich applikations-/OEM-spezifisch implementiert. Entwickler müssen sicherstellen, dass die Handler-Logik nicht blockierend arbeitet, um Deadlocks in Fehlersituationen zu verhindern.</li>\n<li><strong>Manifest-Konfiguration:</strong></li>\n<li>In den <em>Adaptive Platform Machine-</em> und <em>Execution Manifesten</em> müssen die <em>Supervision Recovery Actions</em> explizit auf Benachrichtigung des State Managements (<code>RecoveryNotification</code>) konfiguriert sein, anstatt auf direkte Aktionen (wie Watchdog-Reset oder lokale Prozessneustarts durch PHM).</li>\n<li><strong>API-Verbindlichkeit:</strong> Methoden mit dem Stereotyp <code>«aapInformative»</code> stellen Implementierungsrichtlinien dar; der verbindliche Integrationsvertrag besteht primär im Empfang des <code>RecoveryHandler</code>-Signals und der anschließenden Ansteuerung des <code>ara::exec::StateClient</code>.</li>\n</ul>"}, {"id": "FIG-ef5e74fc4e610ab1", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Sequenzdiagramm mit Interaktionsreferenz (<code>ref</code>).</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Adaptive Platform (Release R24-11), Spezifikation <em>AUTOSAR_AP_EXP_SWArchitecture</em>, Kapitel 11 (<em>System Lifecycle Management</em> / <em>Recover from Supervision Failure</em>).</li>\n<li><strong>Technischer Zweck:</strong> Darstellung des kanonischen Recovery-Pfads (<em>Recover by System State Change</em>) nach Auftreten eines Überwachungsfehlers (Supervision Failure). Es demonstriert die strikte Entkopplung zwischen Fehlerdetektion (Platform Health Management, PHM) und Fehlerbehebungsstrategie (State Management, SM) unter Einbeziehung des Prozess-Lifecycle-Managers (Execution Management, EM).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Beteiligte Functional Cluster (Lebenslinien):</strong></li>\n<li><code>«aapFunctionalCluster» :Platform Health Management</code> (PHM): Überwacht Alive-, Deadline- und Logical-Supervisions sowie Health-Channels von Prozessen und Anwendungen.</li>\n<li><code>«aapFunctionalCluster» :State Management</code> (SM): Zentraler Koordinator für Systemzustände, Funktionsgruppenzustände (Function Group States) und fahrzeugspezifische Recovery-Entscheidungen.</li>\n<li><code>«aapFunctionalCluster» :Execution Management</code> (EM): Verantwortlich für Start, Stopp, Determinismus und Zustandsübergänge konfigurierter Prozesse/Function Groups.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong>Stereotypen & Notationen:</strong></li>\n<li><code>«aapFunctionalCluster»</code>: Kennzeichnet funktionale Plattform-Kernkomponenten der AUTOSAR Adaptive Platform.</li>\n<li><code>«aapInformative»</code>: Markiert nicht-normative Schnittstellen, interne Kontrollflüsse oder exemplarische Hilfsfunktionen, die nicht als feste C++-API standardisiert sind.</li>\n<li><code>ref</code>: UML-Interaktionsreferenz auf das ausgelagerte Sub-Szenario <code>Change System State</code>.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong>Schnittstellen & Operationen:</strong></li>\n<li><code>Offer()</code>: Service-Bereitstellung / Registrierung des Recovery-Interfaces von SM gegenüber PHM (typischerweise IPC/ara::com-basiert oder plattform-interne Kopplung).</li>\n<li><code>supervisionFailed()</code> (<code>«aapInformative»</code>): Interner oder watchdog-getriebener Trigger bei Verletzung einer definierten Überwachungsregel (Checkpoint-Zeitfenster, Alive-Zähler, Graph-Traversierung).</li>\n<li><code>handleFailedSupervision()</code> (<code>«aapInformative»</code>): PHM-interne Regelauswertung und Zuordnung der fehlgeschlagenen Supervision zu einer konfigurierten Recovery-Aktion.</li>\n<li><code>RecoveryHandler()</code>: Normative Callback-/Ereignisschnittstelle von PHM an SM zur Signalisierung des aufgetretenen Fehlers samt Kontext.</li>\n<li><code>determineDesiredFGState(): desiredState</code> (<code>«aapInformative»</code>): SM-interne Entscheidungstabelle/Regelwerk zur Bestimmung des neuen Zielzustands der betroffenen Function Group(s).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Initialisierung / Service Offer:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>State Management</code> bietet seine Service-Schnittstelle via <code>Offer()</code> an, sodass PHM den Recovery-Kanal auflösen und binden kann.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Fehlerdetektion (Supervision Failure):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Ein Prozess verletzt eine Überwachungsbedingung. PHM registriert dies über den Trigger <code>supervisionFailed()</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>PHM-interne Evaluierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>PHM führt <code>handleFailedSupervision()</code> aus und ermittelt anhand des <em>Health Channel / Supervision Mapping</em> im Manifest, dass eine Systemreaktion via State Management konfiguriert ist.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Fehlersignalisierung an SM:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>PHM ruft synchron oder asynchron <code>RecoveryHandler()</code> am State Management auf und übergibt die Identifikatoren der gescheiterten Supervision.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Zielzustandsermittlung im SM:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>SM führt <code>determineDesiredFGState()</code> aus. Abhängig von Sicherheitskonzept und Kontext wird ein neuer <code>desiredState</code> für die betroffene Function Group bestimmt (z. B. Fallback auf sicheren Zustand, Degradation oder Neustart-Zustand). Hinweis: Der Zustand kann formal dem aktuellen Zustand entsprechen, falls ein lokaler Prozess-Neustart innerhalb derselben State-Definition projektiert ist.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Zustandstransition via Execution Management:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Übergang in das referenzierte Sequenzfragment <code>ref Change System State</code>: SM interagiert über die <code>ara::exec::StateClient</code>-API mit <code>Execution Management</code>, um die Zielzustände der Function Groups einzusteuern. EM stoppt oder reinitialisiert die entsprechenden Prozesse deterministisch.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Architekturprinzip (Separation of Concerns):</strong> PHM terminiert oder manipuliert in diesem Szenario keine Prozesse eigenmächtig. Die Hoheit über Prozess-Lifecycles liegt exklusiv bei <code>Execution Management</code>, gesteuert durch die fahrzeugspezifische Richtlinienkomponente <code>State Management</code>.</li>\n<li><strong>Implementierungsverantwortung (OEM vs. Tier-1/Stack-Vendor):</strong></li>\n<li>PHM und EM sind standardisierte BSW-Cluster des Stack-Herstellers.</li>\n<li>Das State Management (inkl. <code>RecoveryHandler</code>-Reaktion und <code>determineDesiredFGState</code>) ist maßgeblich applikations-/OEM-spezifisch implementiert. Entwickler müssen sicherstellen, dass die Handler-Logik nicht blockierend arbeitet, um Deadlocks in Fehlersituationen zu verhindern.</li>\n<li><strong>Manifest-Konfiguration:</strong></li>\n<li>In den <em>Adaptive Platform Machine-</em> und <em>Execution Manifesten</em> müssen die <em>Supervision Recovery Actions</em> explizit auf Benachrichtigung des State Managements (<code>RecoveryNotification</code>) konfiguriert sein, anstatt auf direkte Aktionen (wie Watchdog-Reset oder lokale Prozessneustarts durch PHM).</li>\n<li><strong>API-Verbindlichkeit:</strong> Methoden mit dem Stereotyp <code>«aapInformative»</code> stellen Implementierungsrichtlinien dar; der verbindliche Integrationsvertrag besteht primär im Empfang des <code>RecoveryHandler</code>-Signals und der anschließenden Ansteuerung des <code>ara::exec::StateClient</code>.</li>\n</ul>"}], "trans": [{"from": "FIG-4fba55216efbae96", "to": "FIG-ef5e74fc4e610ab1", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
